# Exact independent replay of this issue's fixed inputs/implementation; no labels/SP.
root<-normalizePath(commandArgs(TRUE)[1],mustWork=TRUE);out<-file.path(root,'results/fm15-26102-20261012');impl<-file.path(out,'implementation')
suppressPackageStartupMessages(library(tidyverse));library(jsonlite)
library(beidan,lib.loc=file.path(root,'results/fm15-version-20261012/library'))
source(file.path(impl,'packages/beidan/R/recent_venue_goals.R'),local=TRUE)
reticulate::use_python(file.path(root,'.venv/bin/python'),required=TRUE);reticulate::import('sys',convert=FALSE)$path$insert(0L,file.path(impl,'packages/beidan/inst/python'))
shared<-reticulate::import('beidan_backend.temporal_learning',convert=FALSE);backend<-reticulate::import('beidan_backend.fundamental_probability',convert=FALSE)
m<-fromJSON(file.path(out,'manifest.json'));nm<-fromJSON(file.path(out,'native-manifest.json'));x<-readRDS(file.path(out,m$batch_file));n<-readRDS(file.path(out,nm$native_file))
stopifnot(digest::digest(file=file.path(out,m$batch_file),algo='sha256')==m$sha256,beidan:::.score_margin_hash(x)==m$object_hash)
stopifnot(all(map_chr(file.path(root,x$input_ledger$path),~digest::digest(file=.x,algo='sha256'))==x$input_ledger$sha256))
inv<-fromJSON(file.path(out,'implementation-inventory.json'));stopifnot(all(map_chr(file.path(impl,inv$files$path),~digest::digest(file=.x,algo='sha256'))==inv$files$sha256))
parent<-readRDS(file.path(root,'results/fundamental-issues-20261011/run-20261011T011533.304058Z/26102-frozen.rds'))
ledger<-list()
for(id in names(n$entries)) {
  e<-n$entries[[id]];f<-e$fixture;z<-x$entries[[id]];r<-z$review
  h<-as_tibble(parent$history) |> filter(fixture_id==id) |> mutate(row_key=paste(scope,match_id,sep=':'),event_date=as.character(event_date))
  native<-estimate_recent_venue_goals(h,f[c('fixture_id','issue_id','provider_id','home_id','away_id')],as.character(parent$fixtures$provider_id),shared$Cutoff$decision_epoch('26102',r$cutoff_utc),e$source_hashes,impl,n$policy,'HISTORICAL_DIAGNOSTIC')
  stopifnot(identical(native,e$native))
  policy<-beidan:::build_fm15_tail_judgement(z$base,r,'native-review',z$base$cutoff,list(max_radius=2L,threshold=.1,coefficient=.3,tie_tolerance=1e-12))
  stopifnot(identical(policy,z$policy))
  fx<-tibble(fixture_id=id,issue_id='26102',home=f$home,away=f$away)
  ctx<-backend$build_adjustment_evidence_context(z$evidence_rows,as.list(fx),shared$Cutoff$decision_epoch('26102',r$cutoff_utc),z$bindings,shared$AvailabilityPolicy$historical_proxy('NATIVE_VENUE_MARKET_PRIOR_QUOTES_DIAGNOSTIC_ONLY'),'HISTORICAL_DIAGNOSTIC',impl)
  final<-adjust_score_margin_distribution(z$base,policy$judgement,ctx,fx,z$base$cutoff,impl)
  stopifnot(identical(final,z$final),identical(final,readRDS(file.path(root,z$score_path))),f$handicap==round(f$handicap))
  projected<-project_score_outcomes(final,as.integer(f$handicap),impl)
  expected<-x$probabilities |> filter(fixture_id==id) |> select(names(projected))
  stopifnot(identical(projected,expected))
  ledger[[id]]<-tibble(fixture_id=id,native_identical=TRUE,policy_identical=TRUE,final_receipt_identical=TRUE,projection_identical=TRUE)
  message('Replayed ',id)
}
ledger<-bind_rows(ledger);stopifnot(nrow(ledger)==86L)
write_csv(ledger,file.path(out,'replay-ledger.csv'))
write_json(list(status='FULL_IDENTICAL_REPLAY',fixtures=86L,forecast_sha256=m$sha256,implementation_inventory_sha256=digest::digest(file=file.path(out,'implementation-inventory.json'),algo='sha256'),replay_code_sha256=digest::digest(file=file.path(root,'r/fm15_26102_replay.R'),algo='sha256'),generated_at_utc=format(Sys.time(),'%Y-%m-%dT%H:%M:%SZ',tz='UTC')),file.path(out,'replay-receipt.json'),auto_unbox=TRUE,pretty=TRUE)
